#!/usr/bin/env python3
import sys
import json
import argparse
import os
from urllib.parse import urlparse
import re
from typing import Any, Dict, List, Tuple, Union, Optional
from pathlib import Path
import urllib.request
import urllib.error

# Basic JSON Schema validator
class JSONSchemaValidator:
    def __init__(self, schema, draft=None, assert_format=False):
        self.schema = schema
        self.draft = draft
        self.assert_format = assert_format
        self.errors = []

    def validate(self, instance):
        self.errors = []
        self._validate_schema(instance, self.schema, "")
        return len(self.errors) == 0

    def _validate_schema(self, instance, schema, path):
        if isinstance(schema, bool):
            if not schema:
                self.errors.append(f"Schema is false")
            return

        if not isinstance(schema, dict):
            return

        # Type validation
        if "type" in schema:
            schema_type = schema["type"]
            if isinstance(schema_type, str):
                if not self._check_type(instance, schema_type):
                    self.errors.append(f"{json.dumps(instance)} is not of type \"{schema_type}\"")
                    return
            elif isinstance(schema_type, list):
                if not any(self._check_type(instance, t) for t in schema_type):
                    type_str = "\", \"".join(schema_type)
                    self.errors.append(f"{json.dumps(instance)} is not of type \"{type_str}\"")
                    return

        # Required validation
        if "required" in schema and isinstance(instance, dict):
            for req in schema["required"]:
                if req not in instance:
                    self.errors.append(f"\"{req}\" is a required property")

        # Properties validation
        if "properties" in schema and isinstance(instance, dict):
            for prop, prop_schema in schema["properties"].items():
                if prop in instance:
                    self._validate_schema(instance[prop], prop_schema, path + f"/{prop}")

        # Enum validation
        if "enum" in schema:
            if instance not in schema["enum"]:
                enum_strs = [json.dumps(e) for e in schema["enum"]]
                if len(enum_strs) == 1:
                    enum_str = enum_strs[0]
                elif len(enum_strs) == 2:
                    enum_str = f"{enum_strs[0]} or {enum_strs[1]}"
                else:
                    enum_str = ", ".join(enum_strs[:-1]) + f" or {enum_strs[-1]}"
                self.errors.append(f"{json.dumps(instance)} is not one of {enum_str}")

        # Minimum/Maximum for numbers
        if isinstance(instance, (int, float)) and not isinstance(instance, bool):
            if "minimum" in schema:
                if instance < schema["minimum"]:
                    self.errors.append(f"{instance} is less than the minimum of {schema['minimum']}")
            if "maximum" in schema:
                if instance > schema["maximum"]:
                    self.errors.append(f"{instance} is greater than the maximum of {schema['maximum']}")

        # Items validation for arrays
        if "items" in schema and isinstance(instance, list):
            items_schema = schema["items"]
            if isinstance(items_schema, dict):
                for i, item in enumerate(instance):
                    self._validate_schema(item, items_schema, path + f"/{i}")

        # Format validation
        if self.assert_format and "format" in schema and isinstance(instance, str):
            fmt = schema["format"]
            if not self._validate_format(instance, fmt):
                self.errors.append(f"{json.dumps(instance)} is not a \"{fmt}\"")

    def _check_type(self, instance, schema_type):
        if schema_type == "null":
            return instance is None
        elif schema_type == "boolean":
            return isinstance(instance, bool)
        elif schema_type == "object":
            return isinstance(instance, dict)
        elif schema_type == "array":
            return isinstance(instance, list)
        elif schema_type == "number":
            return isinstance(instance, (int, float)) and not isinstance(instance, bool)
        elif schema_type == "integer":
            return isinstance(instance, int) and not isinstance(instance, bool)
        elif schema_type == "string":
            return isinstance(instance, str)
        return False

    def _validate_format(self, instance, fmt):
        if fmt == "email":
            return "@" in instance and "." in instance
        elif fmt == "uri" or fmt == "url":
            return instance.startswith(("http://", "https://", "ftp://"))
        elif fmt == "date":
            return re.match(r"^\d{4}-\d{2}-\d{2}$", instance) is not None
        elif fmt == "time":
            return re.match(r"^\d{2}:\d{2}:\d{2}$", instance) is not None
        elif fmt == "date-time":
            return "T" in instance or "t" in instance
        elif fmt == "ipv4":
            parts = instance.split(".")
            if len(parts) != 4:
                return False
            try:
                return all(0 <= int(p) <= 255 for p in parts)
            except:
                return False
        elif fmt == "ipv6":
            return ":" in instance
        return True

def validate_schema(schema):
    """Check if schema itself is valid"""
    # Basic schema validation
    if not isinstance(schema, dict):
        return False, "Schema must be an object"

    if "type" in schema:
        valid_types = ["null", "boolean", "object", "array", "number", "integer", "string"]
        schema_type = schema["type"]
        if isinstance(schema_type, str):
            if schema_type not in valid_types:
                return False, f"\"{schema_type}\" is not valid under any of the schemas listed in the 'anyOf' keyword"
        elif isinstance(schema_type, list):
            for t in schema_type:
                if t not in valid_types:
                    return False, f"\"{t}\" is not valid under any of the schemas listed in the 'anyOf' keyword"

    return True, None

def load_json(path):
    try:
        with open(path, 'r') as f:
            return json.load(f)
    except Exception as e:
        print(f"Error loading {path}: {e}", file=sys.stderr)
        sys.exit(1)

def main():
    parser = argparse.ArgumentParser(
        prog="executable",
        description="JSON Schema validator"
    )

    parser.add_argument("schema", help="The JSON Schema to validate with (i.e. schema.json)")
    parser.add_argument("-i", "--instance", dest="instances", action="append", 
                       help="A path to a JSON instance (i.e. filename.json) to validate (may be specified multiple times)")
    parser.add_argument("-d", "--draft", type=int, choices=[4, 6, 7, 2019, 2020],
                       help="Enforce a specific JSON Schema draft")
    parser.add_argument("--assert-format", action="store_true", 
                       help="Turn ON format validation")
    parser.add_argument("--no-assert-format", action="store_true",
                       help="Turn OFF format validation")
    parser.add_argument("--output", choices=["text", "flag", "list", "hierarchical"],
                       default="text", help="Select output style")
    parser.add_argument("-v", "--version", action="store_true",
                       help="Show program's version number and exit")
    parser.add_argument("--errors-only", action="store_true",
                       help="Only show validation errors")
    parser.add_argument("--connect-timeout", type=int, help="Timeout for establishing connections (in seconds)")
    parser.add_argument("--timeout", type=int, help="Total timeout for HTTP requests (in seconds)")
    parser.add_argument("-k", "--insecure", action="store_true",
                       help="Skip TLS certificate verification (dangerous!)")
    parser.add_argument("--cacert", help="Path to a custom CA certificate file (PEM format)")

    args = parser.parse_args()

    if args.version:
        print("Version: 0.41.0")
        sys.exit(0)

    # Load schema
    schema = load_json(args.schema)

    # Determine format assertion setting
    assert_format = args.assert_format
    if args.no_assert_format:
        assert_format = False

    # If no instances provided, just validate the schema
    if not args.instances:
        valid, error = validate_schema(schema)
        if valid:
            print("Schema is valid")
            sys.exit(0)
        else:
            print(f"Schema is invalid. Error: {error}")
            sys.exit(1)

    # Validate instances
    all_valid = True
    for instance_path in args.instances:
        instance = load_json(instance_path)

        validator = JSONSchemaValidator(schema, draft=args.draft, assert_format=assert_format)
        is_valid = validator.validate(instance)

        if args.output == "text":
            if is_valid:
                if not args.errors_only:
                    print(f"{instance_path} - VALID")
            else:
                print(f"{instance_path} - INVALID. Errors:")
                for i, error in enumerate(validator.errors, 1):
                    print(f"{i}. {error}")
                all_valid = False
        elif args.output == "flag":
            output = {
                "instance": instance_path,
                "output": "flag",
                "payload": {"valid": is_valid},
                "schema": args.schema
            }
            print(json.dumps(output))
            if not is_valid:
                all_valid = False
        elif args.output in ["list", "hierarchical"]:
            # For list and hierarchical, we need to output more detailed error info
            # This is a simplified version
            output = {
                "instance": instance_path,
                "output": args.output,
                "payload": {"valid": is_valid, "details": []},
                "schema": args.schema
            }
            print(json.dumps(output))
            if not is_valid:
                all_valid = False

    sys.exit(0 if all_valid else 1)

if __name__ == "__main__":
    main()
