            if isinstance(schema_type, str):
                if not self._check_type(instance, schema_type):
                    self.errors.append(f"{json.dumps(instance)} is not of type \"{schema_type}\"")
                    return
            elif isinstance(schema_type, list):
                if not any(self._check_type(instance, t) for t in schema_type):
                    type_str = "\", \"".join(schema_type)
                    self.errors.append(f"{json.dumps(instance)} is not of type \"{type_str}\"")
                    return

        # Required validation
        if "required" in schema and isinstance(instance, dict):
