                    self.errors.append(f"{instance} is less than the minimum of {schema['minimum']}")
            if "maximum" in schema:
                if instance > schema["maximum"]:
                    self.errors.append(f"{instance} is greater than the maximum of {schema['maximum']}")

        # Items validation for arrays
        if "items" in schema and isinstance(instance, list):
            items_schema = schema["items"]
            if isinstance(items_schema, dict):
                for i, item in enumerate(instance):
                    self._validate_schema(item, items_schema, 
                                        path + f"/{i}",
                                        eval_path + "/items",
                                        inst_loc + f"/{i}",
                                        schema_loc + "/items")

        # Format validation
        if self.assert_format and "format" in schema and isinstance(instance, str):
            fmt = schema["format"]
            if not self._validate_format(instance, fmt):
