        return len(self.errors) == 0

    def _validate_schema(self, instance, schema, path, eval_path, inst_loc, schema_loc):
        if isinstance(schema, bool):
            if not schema:
                self.errors.append(f"Schema is false")
                self.evaluation_details.append({
                    "evaluationPath": eval_path,
                    "instanceLocation": inst_loc,
                    "schemaLocation": schema_loc,
                    "valid": False
                })
            return

        if not isinstance(schema, dict):
            return

        # Type validation
        if "type" in schema:
            schema_type = schema["type"]
            type_valid = False
            if isinstance(schema_type, str):
