                    self.evaluation_details.append({
                        "evaluationPath": eval_path + "/type",
                        "instanceLocation": inst_loc,
                        "schemaLocation": schema_loc + "/type",
                        "valid": False,
                        "errors": {"type": f"{json.dumps(instance)} is not of type \"{schema_type}\""}
                    })
                    return
            elif isinstance(schema_type, list):
                type_valid = any(self._check_type(instance, t) for t in schema_type)
                if not type_valid:
                    type_str = "\", \"".join(schema_type)
                    self.errors.append(f"{json.dumps(instance)} is not of type \"{type_str}\"")
                    return

            if type_valid:
                self.evaluation_details.append({
                    "evaluationPath": eval_path + "/type",
                    "instanceLocation": inst_loc,
                    "schemaLocation": schema_loc + "/type",
                    "valid": True
                })

        # Required validation
        if "required" in schema and isinstance(instance, dict):
            for req in schema["required"]:
                if req not in instance:
                    self.errors.append(f"\"{req}\" is a required property")

            if any(req not in instance for req in schema["required"]):
                req_errors = {req: f"\"{req}\" is a required property" 
                             for req in schema["required"] if req not in instance}
                self.evaluation_details.append({
                    "evaluationPath": eval_path + "/required",
                    "instanceLocation": inst_loc,
                    "schemaLocation": schema_loc + "/required",
                    "valid": False,
                    "errors": req_errors
                })

        # Properties validation
        if "properties" in schema and isinstance(instance, dict):
            props_valid = True
            dropped_annotations = []
            for prop, prop_schema in schema["properties"].items():
                if prop in instance:
                    self._validate_schema(instance[prop], prop_schema, 
                                        path + f"/{prop}", 
                                        eval_path + "/properties/" + prop,
                                        inst_loc + "/" + prop,
                                        schema_loc + "/properties/" + prop)
                else:
                    dropped_annotations.append(prop)

            if not all(req in instance for req in schema.get("required", [])):
                props_valid = False

            props_detail = {
                "evaluationPath": eval_path + "/properties",
                "instanceLocation": inst_loc,
                "schemaLocation": schema_loc + "/properties",
                "valid": props_valid
            }
            if dropped_annotations:
                props_detail["droppedAnnotations"] = dropped_annotations
            self.evaluation_details.append(props_detail)

